#!/usr/bin/env python3
"""
Round 183b (culprits), 5 October 2026. Needs round 182b.

Glass Garden, a light-filled glass basemap.

Run from the repository root (the apply-patch workflow does).
"""
import base64, pathlib, subprocess, sys, tempfile

NOTES = ["## Round 183b (5 October)\n\nNeeds round 182b (guards on its heading). No tiles patch. No app.js?v= bump.\n\n- Owner asked again for a basemap like their two pictures (seaside room,\n  desk by a window: aqua, white, glass) and the house and plants of Ex\n  Machina: \"dreamy, light-filled, glowing plant and water realm of glass,\n  hazy and see-through\". Aqua (180b) was too pale (\"baby blue\"); Glass house\n  (181b) was too dark and grey and did not read as glass or light.\n- New basemap Glass Garden (kind \"lumen\", layers \"outline-lumen-...\"), on\n  the menu after Bioluminescent. Made like Woodlands from the real Earth\n  (EOX Sentinel-2 through woodComposite, lumenPaintPixels in two Web Workers):\n  plants on teals from deep shade to luminous jade, brighter the denser they\n  grow, with a soft teal light round dense growth; bare ground as clear pale\n  glass; water deep blue-teal to clear turquoise; a thin pale rim where the\n  ground's own brightness changes sharply (light on glass edges); mostly\n  sharp (focus 0.22).\n- Over it: see-through sea by depth, turquoise shallows; high bright\n  north-west light with deep teal shade; haze only on low coasts and the\n  globe's rim; white roads with a faint teal glow; see-through pale glass\n  buildings from zoom 13 (opacity 0.62); sky pale aqua to white.\n- Names: THEMED_NAMES.lumen, Jost Light capitals widely spaced, deep\n  sea-teal on a pale halo. Layer colours default to \"deep\".\n- Tests check: hues teal to cobalt or pale grey only; forest deep and full\n  (not washed out) but lit (not grey); bare ground light; water full\n  blue-teal; a pale rim at forest edges. Not seen against the real imagery\n  (EOX blocked here).\n"]

DIFF = ""


def git(*a, check=True):
    return subprocess.run(["git", *a], capture_output=True, text=True, check=check)


def main():
    root = pathlib.Path(".")
    if not (root / "map" / "app.js").exists():
        sys.exit("round183b: run from the culprits repository root")
    h = root / "HANDOFF.md"
    if "## Round 182b" not in h.read_text(encoding="utf-8"):
        sys.exit("round183b: round 182b must be applied first")
    with tempfile.NamedTemporaryFile("wb", suffix=".diff", delete=False) as f:
        f.write(base64.b64decode(DIFF))
        path = f.name
    if git("apply", "--check", "-R", path, check=False).returncode == 0:
        print("round183b: already applied")
    else:
        r = git("apply", "--3way", path, check=False)
        if r.returncode != 0:
            git("checkout", "--", "map/app.js", "map/test.mjs", check=False)
            sys.exit("round183b: the diff did not apply:\n" + r.stdout + r.stderr)
        print("round183b: applied")
    text = h.read_text(encoding="utf-8")
    add = "".join(n if n.endswith("\n\n") else n.rstrip("\n") + "\n\n" for n in NOTES if n.split("\n", 1)[0] not in text)
    if add:
        at = text.index("\n## Round ") + 1
        h.write_text(text[:at] + add + text[at:], encoding="utf-8")


if __name__ == "__main__":
    main()
